<div class="admin-entity-layout orders-layout"><section class="form-card"><h2><?= $editar ? 'Editar pedido #' . (int) $editar['id'] : 'Novo pedido' ?></h2><form method="post" action="../controllers/pedidos.php"><input type="hidden" name="csrf_token" value="<?= hPedido(gerarTokenCsrf()) ?>"><input type="hidden" name="acao" value="<?= $editar ? 'atualizar' : 'criar' ?>"><?php if ($editar): ?><input type="hidden" name="id" value="<?= (int) $editar['id'] ?>"><p class="field-help">Total: R$ <?= number_format((float) $editar['total'], 2, ',', '.') ?></p><div class="field"><label for="status-pedido">Status</label><select id="status-pedido" name="status"><option value="confirmado" <?= $editar['status'] === 'confirmado' ? 'selected' : '' ?>>Confirmado</option><option value="cancelado" <?= $editar['status'] === 'cancelado' ? 'selected' : '' ?>>Cancelado</option></select></div><?php else: ?><div class="field"><label for="cliente-pedido">Cliente</label><select id="cliente-pedido" name="usuario_id" required><option value="">Selecione</option><?php foreach ($usuarios as $usuario): if ($usuario['tipo'] !== 'user') continue; ?><option value="<?= (int) $usuario['id'] ?>"><?= hPedido($usuario['nome']) ?> (<?= hPedido($usuario['email']) ?>)</option><?php endforeach; ?></select></div><div class="field"><label for="game-pedido">Jogo</label><select id="game-pedido" name="game_id" required><option value="">Selecione</option><?php foreach ($games as $game): if ((int) $game['estoque'] < 1) continue; ?><option value="<?= (int) $game['id'] ?>"><?= hPedido($game['titulo']) ?> (<?= (int) $game['estoque'] ?> disponíveis)</option><?php endforeach; ?></select></div><div class="field"><label for="quantidade-pedido">Quantidade</label><input id="quantidade-pedido" name="quantidade" type="number" min="1" max="99" value="1" required></div><?php endif; ?><div class="field"><label for="obs-pedido">Observação</label><input id="obs-pedido" name="observacao" maxlength="255" value="<?= hPedido((string) ($editar['observacao'] ?? '')) ?>"></div><div class="form-actions"><button type="submit"><?= $editar ? 'Salvar pedido' : 'Criar pedido' ?></button><?php if ($editar): ?><a class="button button-secondary" href="pedidos.php">Cancelar edição</a><?php endif; ?></div></form></section>
<section class="table-shell"><table class="entity-table orders-table"><thead><tr><th>Pedido</th><th>Cliente e itens</th><th>Total</th><th>Status</th><th>Ações</th></tr></thead><tbody><?php foreach ($pedidos as $pedido): ?><tr><td>#<?= (int) $pedido['id'] ?><br><small><?= hPedido(date('d/m/Y', strtotime($pedido['created_at']))) ?></small></td><td><strong><?= hPedido($pedido['cliente']) ?></strong><br><small><?= hPedido((string) $pedido['itens']) ?></small></td><td>R$ <?= number_format((float) $pedido['total'], 2, ',', '.') ?></td><td><?= $pedido['status'] === 'cancelado' ? 'Cancelado' : 'Confirmado' ?></td><td><div class="row-actions"><a class="button button-secondary" href="pedidos.php?editar=<?= (int) $pedido['id'] ?>">Editar</a><form method="post" action="../controllers/pedidos.php" onsubmit="return confirm('Excluir este pedido?')"><input type="hidden" name="csrf_token" value="<?= hPedido(gerarTokenCsrf()) ?>"><input type="hidden" name="acao" value="excluir"><input type="hidden" name="id" value="<?= (int) $pedido['id'] ?>"><button class="button button-danger" type="submit">Excluir</button></form></div></td></tr><?php endforeach; ?></tbody></table><?php if (!$pedidos): ?><p class="admin-empty">Nenhum pedido registrado.</p><?php endif; ?></section></div></main></body></html>
